import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extended-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function write(root, name, content = 'abc') {
  fs.mkdirSync(path.dirname(path.join(root, name)), {recursive:true});
  fs.writeFileSync(path.join(root, name), content);
  fs.chmodSync(path.join(root, name), 0o640);
}
const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
const cli = (...args) => spawnSync(process.execPath, [script, ...args], {encoding:'utf8'});

test('all drift categories, ordered reasons, and sorted immutable inputs', t => {
  const root = fixture(t);
  const names = ['z', 'ä', 'Z', 'a', 'both', 'mode', 'size', 'gone/child', 'link/child', 'blocked/child', 'directory'];
  names.forEach(name => write(root, name));
  const manifest = createManifest(root, Object.freeze(names));
  assert.deepEqual(manifest.files.map(e => e.path), [...names].sort());
  manifest.files.reverse();
  manifest.files.find(e => e.path === 'size').size++;
  manifest.files.forEach(Object.freeze);
  Object.freeze(manifest.files);
  Object.freeze(manifest);
  fs.writeFileSync(path.join(root, 'a'), 'xyz');
  fs.writeFileSync(path.join(root, 'both'), 'longer');
  fs.chmodSync(path.join(root, 'both'), 0o600);
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  for (const name of ['gone', 'link', 'blocked', 'directory']) fs.rmSync(path.join(root, name), {recursive:true});
  fs.symlinkSync(root, path.join(root, 'link'));
  write(root, 'blocked');
  fs.mkdirSync(path.join(root, 'directory'));
  assert.deepEqual(verifyManifest(root, manifest), {
    ok:false, unchanged:['Z', 'z', 'ä'],
    changed:[{path:'a', reasons:['content']}, {path:'both', reasons:['content', 'mode']},
      {path:'mode', reasons:['mode']}, {path:'size', reasons:['content']}],
    missing:['gone/child'], unsafe:['blocked/child', 'directory', 'link/child'],
  });
});

test('invalid manifests and selections throw; unusual filenames and extra fields work', t => {
  const root = fixture(t);
  const name = 'space tab\tline\n雪';
  write(root, name, Buffer.from([0, 255, 13, 10]));
  const manifest = createManifest(root, [name]);
  manifest.extra = true;
  manifest.files[0].extra = true;
  assert.equal(verifyManifest(root, manifest).ok, true);
  const entry = manifest.files[0];
  const invalid = [null, [], {}, {version:2, files:[]}, {version:1, files:{}},
    {version:1, files:[entry, entry]}, ...[null, [], {},
      ...['', '/a', 'a\\b', 'a\0b', 'a//b', './a', 'a/../b', 'a/'].map(p => ({...entry, path:p})),
      ...['A'.repeat(64), '0'.repeat(64) + '\n', '0'.repeat(63), 123].map(sha256 => ({...entry, sha256})),
      ...[-1, 1.5, Infinity, Number.MAX_SAFE_INTEGER + 1, '4'].map(size => ({...entry, size})),
      ...[-1, 512, 1.5, '420'].map(mode => ({...entry, mode})),
    ].map(e => ({version:1, files:[e]}))];
  for (const value of invalid) assert.throws(() => verifyManifest(root, value), Error);
  for (const selected of ['', '/a', 'a\\b', 'a\0b', 'a//b', '.', '..', 'a/']) {
    assert.throws(() => createManifest(root, [selected]), Error);
  }
  assert.throws(() => createManifest(root, [name, name]), Error);
  assert.deepEqual(createManifest(root, []), {version:1, files:[]});
});

test('rejects root symlinks and classifies final symlinks without following them', t => {
  const root = fixture(t);
  write(root, 'file');
  const manifest = createManifest(root, ['file']);
  fs.symlinkSync(root, path.join(root, 'root-link'));
  for (const candidate of [path.join(root, 'root-link'), path.join(root, 'root-link') + '/', path.join(root, 'file'), path.join(root, 'absent')]) {
    assert.throws(() => createManifest(candidate, []), Error);
    assert.throws(() => verifyManifest(candidate, {version:1, files:[]}), Error);
  }
  fs.unlinkSync(path.join(root, 'file'));
  fs.symlinkSync('absent', path.join(root, 'file'));
  assert.deepEqual(verifyManifest(root, manifest).unsafe, ['file']);
  assert.throws(() => createManifest(root, ['file']), Error);
});

test('CLI emits exactly JSON plus newline, correct exit codes, and errors only on stderr', t => {
  const root = fixture(t);
  write(root, 'file');
  const created = cli('create', root, 'file');
  assert.equal(created.status, 0);
  assert.equal(created.stderr, '');
  assert.equal(created.stdout, JSON.stringify(createManifest(root, ['file'])) + '\n');
  const manifestFile = path.join(root, 'manifest.json');
  fs.writeFileSync(manifestFile, created.stdout);
  for (const drift of [false, true]) {
    if (drift) write(root, 'file', 'different');
    const verified = cli('verify', root, manifestFile);
    assert.equal(verified.status, drift ? 1 : 0);
    assert.equal(verified.stderr, '');
    assert.equal(verified.stdout, JSON.stringify(verifyManifest(root, JSON.parse(created.stdout))) + '\n');
  }
  fs.writeFileSync(path.join(root, 'bad.json'), '{');
  fs.writeFileSync(path.join(root, 'invalid.json'), '{}');
  for (const args of [[], ['create'], ['unknown', root], ['verify', root], ['verify', root, manifestFile, 'extra'],
    ['create', root, '../escape'], ['create', path.join(root, 'absent')],
    ...['bad.json', 'invalid.json', 'absent'].map(f => ['verify', root, path.join(root, f)])]) {
    const result = cli(...args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.length > 0);
  }
  const imported = spawnSync(process.execPath, ['--input-type=module', '-e', `import ${JSON.stringify(new URL('../snapshot.js', import.meta.url).href)}`], {encoding:'utf8'});
  assert.equal(imported.status, 0);
  assert.equal(imported.stdout, '');
  assert.equal(imported.stderr, '');
});

